run('post-process', [postProc]);
run('clean source backup', [patcher, '--capture-clean-source']);
run('patcher', [patcher]);

writeFileSync(join(here, '.source-version'), basename(nativeBin) + '\n');
console.log(`[clawgod] re-patched to ${basename(nativeBin)}`);
